diff --git a/src/librawspeed/decoders/Rw2Decoder.cpp b/src/librawspeed/decoders/Rw2Decoder.cpp
index 5aa942680..80ce641e0 100644
--- a/src/librawspeed/decoders/Rw2Decoder.cpp
+++ b/src/librawspeed/decoders/Rw2Decoder.cpp
@@ -23,7 +23,6 @@
 #include "adt/Array1DRef.h"
 #include "adt/Array1DRefExtras.h"
 #include "adt/Array2DRef.h"
-#include "adt/CroppedArray2DRef.h"
 #include "adt/Point.h"
 #include "bitstreams/BitStreams.h"
 #include "common/BayerPhase.h"
@@ -278,32 +277,6 @@ getInputStrips(const DecompressorV8Params& mParams, Buffer mInputFile) {
   return mStrips;
 }

-std::vector<CroppedArray2DRef<uint16_t>>
-getOutputTiles(const DecompressorV8Params& mParams,
-               const Array2DRef<uint16_t> img) {
-  std::vector<CroppedArray2DRef<uint16_t>> mOutTiles;
-
-  const int totalStrips =
-      mParams.horizontalStripCount * mParams.verticalStripCount;
-
-  for (int stripIdx = 0; stripIdx < totalStrips; ++stripIdx) {
-    const uint32_t stripWidth = mParams.stripWidths[stripIdx];
-    const uint32_t stripHeight = mParams.stripHeights[stripIdx];
-    const uint32_t stripOutputX = mParams.stripLineOffsets[stripIdx] & 0xFFFF;
-    const uint32_t stripOutputY = mParams.stripLineOffsets[stripIdx] >> 16;
-
-    const auto out =
-        CroppedArray2DRef<uint16_t>(img, /*offsetCols=*/stripOutputX,
-                                    /*offsetRows=*/stripOutputY,
-                                    /*croppedWidth=*/stripWidth,
-                                    /*croppedHeight=*/stripHeight);
-
-    mOutTiles.emplace_back(out);
-  }
-
-  return mOutTiles;
-}
-
 } // namespace

 RawImage Rw2Decoder::decodeRawV8(const TiffIFD& raw) const {
@@ -320,16 +293,14 @@ RawImage Rw2Decoder::decodeRawV8(const TiffIFD& raw) const {

   mRaw->createData();

-  const auto mOutTiles =
-      getOutputTiles(mParams, mRaw->getU16DataAsUncroppedArray2DRef());
-
-  PanasonicV8Decompressor::DecompressorParams mParams2{
-      .mStrips = getAsArray1DRef(mStrips),
-      .mOutTiles = getAsArray1DRef(mOutTiles),
-      .initialPrediction = mParams.initialPrediction,
-  };
+  PanasonicV8Decompressor::DecompressorParamsBuilder b(
+      mRaw->getU16DataAsUncroppedArray2DRef(), mParams.initialPrediction,
+      getAsArray1DRef(mStrips), getAsArray1DRef(mParams.stripLineOffsets),
+      getAsArray1DRef(mParams.stripWidths),
+      getAsArray1DRef(mParams.stripHeights));

-  PanasonicV8Decompressor v8(mRaw, mParams2, getAsArray1DRef(mHuffmanLUT));
+  PanasonicV8Decompressor v8(mRaw, b.getDecompressorParams(),
+                             getAsArray1DRef(mHuffmanLUT));
   v8.decompress();
   return mRaw;
 }
diff --git a/src/librawspeed/decompressors/PanasonicV8Decompressor.cpp b/src/librawspeed/decompressors/PanasonicV8Decompressor.cpp
index 4b9b350cf..3cc0bc23d 100644
--- a/src/librawspeed/decompressors/PanasonicV8Decompressor.cpp
+++ b/src/librawspeed/decompressors/PanasonicV8Decompressor.cpp
@@ -23,6 +23,7 @@
 #include "rawspeedconfig.h"
 #include "decompressors/PanasonicV8Decompressor.h"
 #include "adt/Array1DRef.h"
+#include "adt/Array1DRefExtras.h"
 #include "adt/Array2DRef.h"
 #include "adt/CroppedArray2DRef.h"
 #include "adt/Invariant.h"
@@ -44,6 +45,7 @@
 #include <cstdint>
 #include <limits>
 #include <utility>
+#include <vector>

 namespace rawspeed {

@@ -198,13 +200,34 @@ void isValidImageGrid(Array2DRef<uint16_t> img,

 } // namespace

-void PanasonicV8Decompressor::DecompressorParams::validate(
-    Array2DRef<uint16_t> img) const {
-  if (mOutTiles.size() != mStrips.size())
-    ThrowRDE("Strip byte buffer array does not have enough entries for the "
-             "number of strips!");
+std::vector<CroppedArray2DRef<uint16_t>>
+PanasonicV8Decompressor::DecompressorParamsBuilder::getOutTiles(
+    Array2DRef<uint16_t> img, Array1DRef<const uint32_t> stripLineOffsets,
+    Array1DRef<const uint16_t> stripWidths,
+    Array1DRef<const uint16_t> stripHeights) {
+  const int totalStrips = stripLineOffsets.size();
+  invariant(stripWidths.size() == totalStrips &&
+            stripHeights.size() == totalStrips);
+
+  std::vector<CroppedArray2DRef<uint16_t>> mOutTiles;
+
+  for (int stripIdx = 0; stripIdx < totalStrips; ++stripIdx) {
+    const uint32_t stripWidth = stripWidths(stripIdx);
+    const uint32_t stripHeight = stripHeights(stripIdx);
+    const uint32_t stripOutputX = stripLineOffsets(stripIdx) & 0xFFFF;
+    const uint32_t stripOutputY = stripLineOffsets(stripIdx) >> 16;
+
+    const auto out =
+        CroppedArray2DRef<uint16_t>(img, /*offsetCols=*/stripOutputX,
+                                    /*offsetRows=*/stripOutputY,
+                                    /*croppedWidth=*/stripWidth,
+                                    /*croppedHeight=*/stripHeight);
+
+    mOutTiles.emplace_back(out);
+  }

-  isValidImageGrid(img, mOutTiles);
+  isValidImageGrid(img, getAsArray1DRef(mOutTiles));
+  return mOutTiles;
 }

 ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
@@ -219,7 +242,6 @@ PanasonicV8Decompressor::PanasonicV8Decompressor(
       mRawOutput->getBpp() != sizeof(uint16_t)) {
     ThrowRDE("Unexpected component count / data type");
   }
-  mParams.validate(mRawOutput->getU16DataAsUncroppedArray2DRef());
 }

 void PanasonicV8Decompressor::decompress() const {
diff --git a/src/librawspeed/decompressors/PanasonicV8Decompressor.h b/src/librawspeed/decompressors/PanasonicV8Decompressor.h
index f6ccbda5e..7936451c2 100644
--- a/src/librawspeed/decompressors/PanasonicV8Decompressor.h
+++ b/src/librawspeed/decompressors/PanasonicV8Decompressor.h
@@ -23,12 +23,14 @@
 #pragma once

 #include "adt/Array1DRef.h"
+#include "adt/Array1DRefExtras.h"
 #include "adt/Array2DRef.h"
 #include "adt/CroppedArray2DRef.h"
 #include "common/RawImage.h"
 #include "decompressors/AbstractDecompressor.h"
 #include <array>
 #include <cstdint>
+#include <vector>

 namespace rawspeed {

@@ -51,13 +53,52 @@ class PanasonicV8Decompressor final : public AbstractDecompressor {

   /// Decompressor parameters populated from tags. They remain constant after
   /// construction.
+  struct DecompressorParamsBuilder;
+
   struct DecompressorParams {
     const Array1DRef<const Array1DRef<const uint8_t>> mStrips;
     const Array1DRef<const CroppedArray2DRef<uint16_t>> mOutTiles;

     const Bayer2x2 initialPrediction;

-    void validate(Array2DRef<uint16_t> img) const;
+    DecompressorParams() = delete;
+
+  private:
+    friend struct DecompressorParamsBuilder;
+
+    DecompressorParams(Array1DRef<const Array1DRef<const uint8_t>> mStrips_,
+                       Array1DRef<const CroppedArray2DRef<uint16_t>> mOutTiles_,
+                       Bayer2x2 initialPrediction_)
+        : mStrips(mStrips_), mOutTiles(mOutTiles_),
+          initialPrediction(initialPrediction_) {
+      invariant(mStrips.size() == mOutTiles.size());
+    }
+  };
+
+  struct DecompressorParamsBuilder {
+    const Array1DRef<const Array1DRef<const uint8_t>> mStrips;
+    const Bayer2x2 initialPrediction;
+
+    const std::vector<CroppedArray2DRef<uint16_t>> mOutTiles;
+
+    std::vector<CroppedArray2DRef<uint16_t>> static getOutTiles(
+        Array2DRef<uint16_t> img, Array1DRef<const uint32_t> stripLineOffsets,
+        Array1DRef<const uint16_t> stripWidths,
+        Array1DRef<const uint16_t> stripHeights);
+
+    DecompressorParamsBuilder(
+        Array2DRef<uint16_t> img, Bayer2x2 initialPrediction_,
+        Array1DRef<const Array1DRef<const uint8_t>> mStrips_,
+        Array1DRef<const uint32_t> stripLineOffsets,
+        Array1DRef<const uint16_t> stripWidths,
+        Array1DRef<const uint16_t> stripHeights)
+        : mStrips(mStrips_), initialPrediction(initialPrediction_),
+          mOutTiles(
+              getOutTiles(img, stripLineOffsets, stripWidths, stripHeights)) {}
+
+    [[nodiscard]] DecompressorParams getDecompressorParams() const {
+      return {mStrips, getAsArray1DRef(mOutTiles), initialPrediction};
+    }
   };

   // Pre-cached Huffman decoded values for rapid lookup.
diff --git a/src/librawspeed/io/ByteStream.h b/src/librawspeed/io/ByteStream.h
index c57e568a6..5ef018071 100644
--- a/src/librawspeed/io/ByteStream.h
+++ b/src/librawspeed/io/ByteStream.h
@@ -170,6 +170,16 @@ class ByteStream final : public DataBuffer {
     return out;
   }

+  template <typename T> std::vector<T> getVector(int nElt) {
+    std::vector<T> out;
+    auto bs = getStream(nElt, sizeof(T));
+    out.reserve(nElt);
+    std::generate_n(std::back_inserter(out), nElt,
+                    [&bs]() { return bs.get<T>(); });
+    invariant(bs.getRemainSize() == 0);
+    return out;
+  }
+
   [[nodiscard]] uint8_t peekByte(size_type i = 0) const {
     return peek<uint8_t>(i);
   }
